mapper.select:
SELECT * FROM ( SELECT SHMV.APKIHONCD, SHMV.SHOPCD, SHMV.SHNCD, ( CASE WHEN SHMV.SHNNMKIRIKAEDD <= #{unyoymd} THEN SHMV.SHINSHNNM ELSE SHMV.GENZSHNNM END ) SHNNM, ( CASE WHEN SHMV.SHNNMKIRIKAEDD <= #{unyoymd} THEN SHMV.SHINSHNNMRYAKUSHO ELSE SHMV.GENZSHNNMRYAKUSHO END ) SHNNMRYAKUSHO, SHMV.STKBN, STKBNNM.ITEMNM AS STKBNNM, ( CASE WHEN SHMV.HYOJUNPRICEKIRIKAEDD <= #{unyoymd} THEN SHINPRICEKBNNM.ITEMNM ELSE GENPRICEKBNNM.ITEMNM END ) PRICEKBN, SHMV.LCTGRYCD, SHMV.MCTGRYCD, SHMV.SCTGRYCD, SHMV.HANBAISTRTDD, SHMV.HANBAISHRYDD, ( CASE WHEN SHMV.SHNPOINTKIRIKAEDD <= #{unyoymd} THEN SHMV.SHINSHNPOINTHASSEIKBN ELSE SHMV.GENSHNPOINTHASSEIKBN END ) SHNPOINTHASSEIKBN, ( CASE WHEN SHMV.SHNPOINTKIRIKAEDD <= #{unyoymd} THEN SHMV.SHINSHNPOINTSU ELSE SHMV.GENSHNPOINTSU END ) SHNPOINTSU, ( CASE WHEN SHMV.MTMKIPOINTKIRIKAEDD <= #{unyoymd} THEN SHMV.SHINMTMKIPOINTKBN ELSE SHMV.GENMTMKIPOINTKBN END ) MTMKIPOINTKBN, ( CASE WHEN SHMV.MTMKIPOINTKIRIKAEDD <= #{unyoymd} THEN SHMV.SHINMTMKISURYO ELSE SHMV.GENMTMKISURYO END ) MTMKISURYO, ( CASE WHEN SHMV.MTMKIPOINTKIRIKAEDD <= #{unyoymd} THEN SHMV.SHINMTMKIPOINTSU ELSE SHMV.GENMTMKIPOINTSU END ) MTMKIPOINTSU, SHMV.SHOPYUKOKBN AS YUKOKBN, YUKOKBNNM.ITEMNM AS YUKOKBNNM FROM S02V200T SHMV LEFT JOIN S01M004T STKBNNM ON STKBNNM.CONDITIONID = 'CN025' AND STKBNNM.SETTEIATAI = SHMV.STKBN LEFT JOIN S01M004T GENPRICEKBNNM ON GENPRICEKBNNM.CONDITIONID = 'CN028' AND GENPRICEKBNNM.SETTEIATAI = SHMV.GENZPRICEKBN LEFT JOIN S01M004T SHINPRICEKBNNM ON SHINPRICEKBNNM.CONDITIONID = 'CN028' AND SHINPRICEKBNNM.SETTEIATAI = SHMV.SHINPRICEKBN LEFT JOIN S01M004T YUKOKBNNM ON YUKOKBNNM.CONDITIONID = 'CN001' AND YUKOKBNNM.SETTEIATAI = SHMV.SHOPYUKOKBN WHERE SHMV.APKIHONCD = #{apkihoncd} AND SHMV.SHOPCD = #{shopcd} AND SHMV.TRTSKIKBN NOT IN ('2')
AND SHMV.STKBN = '0'
AND SHMV.STKBN = '1'
AND SHMV.SHNCD LIKE #{shncd} || '%'
AND ( CASE WHEN #{unyoymd} < SHMV.SHNNMKIRIKAEDD THEN SHMV.GENZSHNNM ELSE SHMV.SHINSHNNM END ) LIKE '%' || #{shnnm} || '%'
AND SHMV.LCTGRYCD = #{lctgrycd}
AND SHMV.MCTGRYCD = #{mctgrycd}
AND SHMV.SCTGRYCD = #{sctgrycd}
AND ( CASE WHEN #{unyoymd} < HYOJUNPRICEKIRIKAEDD THEN GENZPRICEKBN ELSE SHINPRICEKBN END ) = '1'
AND ( CASE WHEN #{unyoymd} < HYOJUNPRICEKIRIKAEDD THEN GENZPRICEKBN ELSE SHINPRICEKBN END ) = '2'
AND TO_DATE(HANBAISTRTDD, 'YYYY/MM/DD') BETWEEN #{hanbaistrtddstr} AND #{hanbaistrtddend}
AND TO_DATE(HANBAISHRYDD, 'YYYY/MM/DD') BETWEEN #{hanbaishryddstr} AND #{hanbaishryddend}
AND SHMV.SHOPYUKOKBN = '1'
AND SHMV.SHOPYUKOKBN = '0'
AND ( CASE WHEN #{unyoymd} < SHMV.MTMKIPOINTKIRIKAEDD THEN GENMTMKIPOINTKBN ELSE SHINMTMKIPOINTKBN END ) IN ('1','2','3')
AND ( CASE WHEN #{unyoymd} < SHMV.MTMKIPOINTKIRIKAEDD THEN GENMTMKIPOINTKBN ELSE SHINMTMKIPOINTKBN END ) = '0'
AND ( CASE WHEN #{unyoymd} < SHMV.SHNPOINTKIRIKAEDD THEN SHMV.GENSHNPOINTHASSEIKBN ELSE SHMV.SHINSHNPOINTHASSEIKBN END IN
#{val}
)
AND SHMV.LCTGRYCD = '01' AND SHMV.MGNTRGTKBN＝'1'
AND SHMV.LCTGRYCD = '01'
AND SHMV.LCTGRYCD = '10'
ORDER BY SHMV.APKIHONCD, SHMV.SHOPCD, SHMV.SHNCD ) WHERE ROWNUM <= #{rownum} + 1
